WITH sales_union AS ( SELECT ss_sold_date_sk AS sold_date_sk, ss_net_profit AS net_profit FROM store_sales UNION ALL SELECT ws_sold_date_sk AS sold_date_sk, ws_net_profit AS net_profit FROM web_sales ), quarter_agg AS ( SELECT d.d_year, d.d_quarter_name, SUM(su.net_profit) AS total_net_profit FROM sales_union su JOIN date_dim d ON su.sold_date_sk = d.d_date_sk GROUP BY d.d_year, d.d_quarter_name ), quarter_with_lag AS ( SELECT d_year, d_quarter_name, total_net_profit, LAG(total_net_profit) OVER (PARTITION BY d_quarter_name ORDER BY d_year) AS prior_year_profit FROM quarter_agg ) SELECT d_year, d_quarter_name, total_net_profit, prior_year_profit, CASE WHEN prior_year_profit IS NULL OR prior_year_profit = 0 THEN NULL ELSE ROUND((total_net_profit - prior_year_profit) / prior_year_profit * 100, 2) END AS yoy_growth_pct, DENSE_RANK() OVER (ORDER BY total_net_profit DESC) AS profit_rank FROM quarter_with_lag ORDER BY d_year, d_quarter_name
